CREATE TABLE `vocabularies` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `level` varchar(2) NOT NULL,
  `word` varchar(255) NOT NULL,
  `part_of_speech` varchar(20) DEFAULT NULL,
  `ipa` varchar(255) DEFAULT NULL,
  `meaning_vi` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vocabularies_level_index` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=9936 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

